package vn.svframe.loadprobe;
import java.nio.file.*;import java.util.*;import net.fabricmc.api.ClientModInitializer;import net.fabricmc.fabric.api.client.command.v2.ClientCommandRegistrationCallback;import static net.fabricmc.fabric.api.client.command.v2.ClientCommandManager.*;
/** Test-only bounded frame sampler, installed identically for A/B graphical client runs. */
public final class FrameProbe implements ClientModInitializer {
 private static final long[] intervals=new long[18000],renders=new long[18000];private static long previous,begin,wall;private static int count,overflow;private static boolean recording;
 public static void begin(){if(recording){long now=System.nanoTime();begin=now;if(previous>0){if(count<intervals.length)intervals[count]=now-previous;else overflow++;}previous=now;}}
 public static void end(){if(recording&&previous>0&&count<renders.length){renders[count++]=System.nanoTime()-begin;}}
 public void onInitializeClient(){ClientCommandRegistrationCallback.EVENT.register((dispatcher,access)->dispatcher.register(literal("frameprobe").then(literal("start").executes(c->{count=overflow=0;previous=0;wall=System.currentTimeMillis();recording=true;return 1;})).then(literal("stop").then(argument("label",com.mojang.brigadier.arguments.StringArgumentType.word()).executes(c->{recording=false;String label=com.mojang.brigadier.arguments.StringArgumentType.getString(c,"label");if(!label.matches("[A-Za-z0-9_-]{1,64}"))return 0;var client=c.getSource().getClient();var m=new LinkedHashMap<String,Object>();m.put("startEpochMs",wall);m.put("endEpochMs",System.currentTimeMillis());m.put("intervalNanos",Arrays.copyOfRange(intervals,1,count));m.put("renderNanos",Arrays.copyOfRange(renders,1,count));m.put("overflow",overflow);m.put("width",client.getWindow().getWidth());m.put("height",client.getWindow().getHeight());m.put("guiScale",client.getWindow().getScaleFactor());m.put("language",client.options.language);try{Path path=client.runDirectory.toPath().resolve("frame-probe/"+label+".json");Files.createDirectories(path.getParent());Files.writeString(path,new com.google.gson.Gson().toJson(m));return 1;}catch(Exception e){throw new RuntimeException(e);}})))));}
}
